package httpapi
import("context";"encoding/json";"net/http";"net/url";"time";"github.com/go-chi/chi/v5")
func(h *Handler)deleteUserMedia(w http.ResponseWriter,r *http.Request){ctx,cancel:=context.WithTimeout(r.Context(),2*time.Minute);defer cancel();userID:=chi.URLParam(r,"userID");query:=url.Values{"limit":[]string{"100"}};deleted:=int64(0);batches:=0;for batches<1000{status,raw,err:=h.synapse.AdminRequest(ctx,http.MethodDelete,"/_synapse/admin/v1/users/"+url.PathEscape(userID)+"/media",query,[]byte("{}"));if err!=nil{h.logger.Warn().Err(err).Str("user_id",userID).Int("status",status).Msg("media deletion batch failed");write(w,http.StatusBadGateway,envelope{OK:false,Error:&apiError{Code:"media_delete_failed",Message:"Synapse could not delete the user's media"}});return};var response struct{Total int64 `json:"total"`};if err=json.Unmarshal(raw,&response);err!=nil{write(w,502,envelope{OK:false,Error:&apiError{Code:"invalid_synapse_response",Message:"Invalid media deletion response"}});return};deleted+=response.Total;batches++;if response.Total<100{break}};write(w,200,envelope{OK:true,Data:map[string]any{"user_id":userID,"deleted":deleted,"batches":batches,"possibly_more":batches==1000}})}
